// @FIGURE_CODE_BEGIN
(function () {
  var A = 155 / (280 * 280);            // parabola coefficient
  var ROOT = 560;
  function h(x) { return A * x * (ROOT - x); }   // height at distance x

  var state = { dist: 200, wall: 400, wallH: 25, sampled: false };

  // build smooth samples
  var smoothPts = [];
  for (var x = 0; x <= ROOT; x += 4) smoothPts.push({ x: x, y: h(x) });
  // build sampled points every 40 ft
  var samplePts = [];
  for (var xs = 0; xs <= ROOT; xs += 40) samplePts.push({ x: xs, y: h(xs) });

  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  document.getElementById('container').appendChild(canvas);

  var TEAL = '#1f8aa3';

  var drawPlugin = {
    id: 'customDraw',
    afterDatasetsDraw: function (chart) {
      var ctx = chart.ctx;
      var sx = chart.scales.x, sy = chart.scales.y;
      var px = function (v) { return sx.getPixelForValue(v); };
      var py = function (v) { return sy.getPixelForValue(v); };
      var minDim = Math.min(chart.width, chart.height);
      var fs = Math.max(9, Math.round(minDim * 0.024));

      function haloText(txt, X, Y, align, color, size) {
        ctx.save();
        ctx.font = (size || fs) + 'px sans-serif';
        ctx.textAlign = align || 'left';
        ctx.textBaseline = 'middle';
        ctx.lineWidth = 3; ctx.strokeStyle = '#fff'; ctx.lineJoin = 'round';
        ctx.strokeText(txt, X, Y);
        ctx.fillStyle = color || '#111';
        ctx.fillText(txt, X, Y);
        ctx.restore();
      }
      function leader(x1, y1, x2, y2) {
        ctx.save(); ctx.strokeStyle = '#333'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); ctx.restore();
      }

      // ---- arrowheads along trajectory ----
      var arrowXs = [80, 180, 300, 420, 520];
      ctx.save(); ctx.fillStyle = TEAL;
      for (var i = 0; i < arrowXs.length; i++) {
        var ax = arrowXs[i];
        var p1x = px(ax), p1y = py(h(ax));
        var p2x = px(ax + 6), p2y = py(h(ax + 6));
        var ang = Math.atan2(p2y - p1y, p2x - p1x);
        var s = Math.max(5, minDim * 0.014);
        ctx.beginPath();
        ctx.moveTo(p1x + Math.cos(ang) * s, p1y + Math.sin(ang) * s);
        ctx.lineTo(p1x + Math.cos(ang + 2.5) * s, p1y + Math.sin(ang + 2.5) * s);
        ctx.lineTo(p1x + Math.cos(ang - 2.5) * s, p1y + Math.sin(ang - 2.5) * s);
        ctx.closePath(); ctx.fill();
      }
      ctx.restore();

      // ---- fixed open circle marker on rising branch ----
      var mx = px(200), my = py(h(200));
      ctx.save();
      ctx.beginPath(); ctx.arc(mx, my, Math.max(4, minDim * 0.011), 0, Math.PI * 2);
      ctx.fillStyle = '#fff'; ctx.fill();
      ctx.lineWidth = 2; ctx.strokeStyle = TEAL; ctx.stroke();
      ctx.restore();
      // leader + label "Trajectory of ball"
      var lbx = px(60), lby = py(205);
      leader(lbx + 70, lby + 8, mx - 4, my - 4);
      haloText('Trajectory of ball', lbx, lby, 'left', '#111');

      // ---- leader "Position of hitter" to origin ----
      var ox = px(0), oy = py(0);
      var phx = px(55), phy = py(35);
      leader(phx - 4, phy + 4, ox + 3, oy - 3);
      haloText('Position of hitter', phx, phy, 'left', '#111');

      // ---- outfield wall (red rectangle) ----
      var wx = px(state.wall);
      var wTop = py(state.wallH), wBase = py(0);
      var wW = Math.max(4, minDim * 0.012);
      ctx.save(); ctx.fillStyle = '#d62728';
      ctx.fillRect(wx - wW / 2, wTop, wW, wBase - wTop);
      ctx.restore();
      haloText('Outfield wall', wx, wTop - fs, 'center', '#111');

      // ---- comparison highlight at wall ----
      var ballH = h(state.wall);
      var clears = ballH > state.wallH;
      var col = clears ? '#2ca02c' : '#d62728';
      ctx.save();
      ctx.strokeStyle = col; ctx.lineWidth = 2; ctx.setLineDash([4, 3]);
      ctx.beginPath(); ctx.moveTo(wx, py(state.wallH)); ctx.lineTo(wx, py(ballH)); ctx.stroke();
      ctx.setLineDash([]);
      ctx.beginPath(); ctx.arc(wx, py(ballH), Math.max(4, minDim * 0.011), 0, Math.PI * 2);
      ctx.fillStyle = col; ctx.fill();
      ctx.restore();
      haloText(clears ? 'clears!' : 'below wall', wx + 8, py(ballH), 'left', col);

      // ---- distance marker: dashed drop line + dot + readout ----
      var dx = px(state.dist), dyTop = py(h(state.dist)), dyBase = py(0);
      ctx.save();
      ctx.strokeStyle = '#555'; ctx.lineWidth = 1.5; ctx.setLineDash([5, 4]);
      ctx.beginPath(); ctx.moveTo(dx, dyTop); ctx.lineTo(dx, dyBase); ctx.stroke();
      ctx.setLineDash([]);
      ctx.beginPath(); ctx.arc(dx, dyTop, Math.max(5, minDim * 0.013), 0, Math.PI * 2);
      ctx.fillStyle = '#ff7f0e'; ctx.fill();
      ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.stroke();
      ctx.restore();
      haloText('h = ' + Math.round(h(state.dist)) + ' ft', dx + 8, dyTop - fs, 'left', '#b45309');
    }
  };

  var chart = new Chart(canvas, {
    type: 'line',
    data: {
      datasets: [
        {
          label: 'Trajectory',
          data: smoothPts,
          parsing: { xAxisKey: 'x', yAxisKey: 'y' },
          borderColor: TEAL, borderWidth: 2.5, pointRadius: 0,
          tension: 0.2, fill: false, order: 2
        },
        {
          label: 'Samples',
          data: samplePts,
          parsing: { xAxisKey: 'x', yAxisKey: 'y' },
          showLine: false, pointRadius: 3.5, pointBackgroundColor: TEAL,
          pointBorderColor: '#fff', pointBorderWidth: 1, hidden: true, order: 1
        }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false,
      animation: { duration: 250 },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: function (c) { return '(' + Math.round(c.parsed.x) + ' ft, ' + Math.round(c.parsed.y) + ' ft)'; }
          }
        }
      },
      scales: {
        x: {
          type: 'linear', min: 0, max: 620,
          ticks: { stepSize: 100, callback: function (v) { return v > 600 ? '' : v; } },
          grid: { color: '#cccccc', borderDash: [2, 3] },
          title: { display: true, text: 'Distance (ft)', font: { size: 13 } }
        },
        y: {
          type: 'linear', min: 0, max: 310,
          ticks: { stepSize: 100, callback: function (v) { return v > 300 ? '' : v; } },
          grid: { color: '#cccccc', borderDash: [2, 3] },
          title: { display: true, text: 'Height (ft)', font: { size: 13 } }
        }
      }
    },
    plugins: [drawPlugin]
  });

  window.__markRendered();

  // ---- interaction handlers ----
  window.update_distanceSlider = function (v) { state.dist = v; chart.update('none'); };
  window.update_wallSlider = function (v) { state.wall = v; chart.update('none'); };
  window.toggle_pathPoints = function (on) {
    state.sampled = on;
    chart.data.datasets[0].hidden = on;     // smooth
    chart.data.datasets[1].hidden = !on;    // samples
    chart.update('none');
  };

  // ---- demo step player ----
  var steps = [
    { title: 'Read the trajectory',
      narration: 'The teal arc leaves the hitter at the origin, climbs to a peak of about 155 ft near 290 ft, and lands near 560 ft; the arrowheads show the ball’s direction of travel.',
      state: { distanceSlider: 200, wallSlider: 400, pathPoints: 'Smooth path' } },
    { title: 'Height at a distance',
      narration: 'Drag the distance marker along the arc: the vertical drop line and height readout update, showing that every distance has exactly one height — the path is a function.',
      state: { distanceSlider: 290, wallSlider: 400, pathPoints: 'Smooth path' } },
    { title: 'Clearing the wall',
      narration: 'Move the wall slider: at 400 ft the ball is far above the short red wall, but slide the wall toward the landing point and the curve dips below the wall height, turning a home run into an out.',
      state: { distanceSlider: 290, wallSlider: 540, pathPoints: 'Smooth path' } },
    { title: 'Curve versus samples',
      narration: 'Toggle to sampled points: the same arc appears as discrete (distance, height) dots on the grid, connecting the smooth graph to a table of values.',
      state: { distanceSlider: 290, wallSlider: 400, pathPoints: 'Sampled points' } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur].state;
    document.getElementById('distanceSliderInput').value = s.distanceSlider;
    document.getElementById('distanceSliderVal').value = s.distanceSlider;
    update_distanceSlider(s.distanceSlider);
    document.getElementById('wallSliderInput').value = s.wallSlider;
    document.getElementById('wallSliderVal').value = s.wallSlider;
    update_wallSlider(s.wallSlider);
    var sampled = (s.pathPoints === 'Sampled points');
    document.getElementById('pathPointsInput').checked = sampled;
    toggle_pathPoints(sampled);
    document.getElementById('demoNarration').textContent =
      (cur + 1) + '/' + steps.length + ' — ' + steps[cur].title + ': ' + steps[cur].narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
  }
  window.prevStep = function () { applyStep(cur - 1); };
  window.nextStep = function () { applyStep(cur + 1); };
  applyStep(0);
})();
// @FIGURE_CODE_END

